const req = $input.first().json;
const auth = String((req.headers || {}).authorization || '').trim();
const jwt = auth.split(' ').pop().split('.')[1] || '';
let email = '';
try {
  email = String(JSON.parse(Buffer.from(jwt, 'base64url').toString('utf8')).sub || '').trim().toLowerCase();
} catch (e) {
  email = '';
}
const corpo = (req.body && typeof req.body === 'object') ? req.body : {};
const t = v => String(v || '').trim();
return [{ json: { auth, email, acao: t(corpo.acao).toLowerCase(), instancia: t(corpo.instancia).toLowerCase(), itens: Array.isArray(corpo.itens) ? corpo.itens : null } }];

const cred = $('Ler Credencial').first().json;
const eu = $('Validar Token no Monint').first().json.body || {};
const admin = String(eu.perfil || '').trim().toUpperCase() === 'ADMIN';
const email = String(eu.email || cred.email).trim().toLowerCase();

// Quem pode importar: todo usuario ADMIN, ou so os e-mails desta lista (vazia = todo ADMIN).
const EMAILS_PERMITIDOS = [];

// Instancias que aceitam importacao. projetoId e o ID do projeto Personal da chave de escrita (na URL do n8n:
// /projects/<ID>/workflows). Enquanto estiver como TROCAR_..., a instancia nao aparece nem recebe importacao.
// Para liberar outra, acrescente uma linha aqui, crie os 3 nodes HTTP dela (Criar Pasta, Criar Workflow, Atualizar
// Workflow, com a credencial de ESCRITA daquela instancia) e uma saida nos 3 nodes "Qual Instancia?".
const INSTANCIAS = {
  automaker_prod: { nome: 'Produção', baseUrl: 'https://n8n-prod.citel.app', projetoId: 'TROCAR_PELO_ID_DO_PROJETO' },
  automaker_1: { nome: 'Automaker 1', baseUrl: 'https://automaker.citelsoftware.com.br', projetoId: 'TROCAR_PELO_ID_DO_PROJETO' },
  automakerdev_geral: { nome: 'Automaker Dev Geral', baseUrl: 'https://automakerdev.citelsoftware.com.br', projetoId: 'zQ1MIpWe3DPkm3hw' }
};
const pronta = i => !!i && !!i.projetoId && !/^TROCAR/.test(i.projetoId);

const emailOk = EMAILS_PERMITIDOS.length === 0 || EMAILS_PERMITIDOS.includes(email);
const existe = Object.prototype.hasOwnProperty.call(INSTANCIAS, cred.instancia) && pronta(INSTANCIAS[cred.instancia]);
const instancias = Object.keys(INSTANCIAS).filter(id => pronta(INSTANCIAS[id])).map(id => ({ id, nome: INSTANCIAS[id].nome }));
return [{ json: {
  permitido: admin && emailOk,
  email,
  acao: cred.acao,
  instancia: cred.instancia,
  itens: cred.itens,
  instancias,
  baseUrl: existe ? INSTANCIAS[cred.instancia].baseUrl : '',
  projetoId: existe ? INSTANCIAS[cred.instancia].projetoId : ''
} }];

const ctx = $('Checar Permissao').first().json;
const ACOES = ['instancias', 'criar-pastas', 'criar-workflows', 'atualizar-workflows'];
const falha = (status, erro) => [{ json: { ok: false, status, erro } }];

if (!ACOES.includes(ctx.acao)) { return falha(400, 'Ação inválida'); }
if (ctx.acao === 'instancias') { return [{ json: { ok: true, acao: ctx.acao } }]; }
if (!ctx.baseUrl) { return falha(403, 'A importação não está liberada para esta instância.'); }

const itens = ctx.itens;
if (!Array.isArray(itens) || itens.length < 1 || itens.length > 25) { return falha(400, 'Envie de 1 a 25 itens por pedido.'); }

const objeto = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const idOk = v => typeof v === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(v);
const vazio = v => v === null || v === undefined;
const PERMITIDOS = ['name', 'nodes', 'connections', 'settings', 'pinData', 'staticData', 'description', 'nodeGroups'];

for (let i = 0; i < itens.length; i++) {
  const it = itens[i];
  const onde = 'item ' + (i + 1) + ': ';
  if (!objeto(it) || typeof it.chave !== 'string' || it.chave.length < 1 || it.chave.length > 600) { return falha(400, onde + 'chave inválida.'); }
  if (ctx.acao === 'criar-pastas') {
    if (typeof it.nome !== 'string' || !it.nome.trim() || it.nome.length > 128) { return falha(400, onde + 'nome de pasta inválido (1 a 128 caracteres).'); }
    if (!vazio(it.paiId) && !idOk(it.paiId)) { return falha(400, onde + 'pasta-mãe inválida.'); }
    continue;
  }
  const w = it.workflow;
  if (!objeto(w)) { return falha(400, onde + 'falta o workflow.'); }
  if (typeof w.name !== 'string' || !w.name.trim() || w.name.length > 128) { return falha(400, onde + 'nome do workflow inválido (1 a 128 caracteres).'); }
  if (!Array.isArray(w.nodes) || w.nodes.length > 3000) { return falha(400, onde + 'lista de nodes inválida.'); }
  if (!objeto(w.connections) || !objeto(w.settings)) { return falha(400, onde + 'connections e settings são obrigatórios.'); }
  const estranho = Object.keys(w).find(k => !PERMITIDOS.includes(k));
  if (estranho) { return falha(400, onde + 'propriedade não permitida: ' + estranho + '.'); }
  if (JSON.stringify(w).length > 8000000) { return falha(400, onde + 'workflow grande demais (limite de 8 MB).'); }
  if (ctx.acao === 'criar-workflows') {
    if (!vazio(it.pastaId) && !idOk(it.pastaId)) { return falha(400, onde + 'pasta inválida.'); }
  } else if (!idOk(it.id)) {
    return falha(400, onde + 'ID do workflow inválido.');
  }
}
return [{ json: { ok: true, acao: ctx.acao } }];

const ctx = $('Checar Permissao').first().json;
return ctx.itens.map(it => ({ json: {
  chave: it.chave,
  baseUrl: ctx.baseUrl,
  projetoId: ctx.projetoId,
  instancia: ctx.instancia,
  corpo: Object.assign({ name: it.nome.trim() }, it.paiId ? { parentFolderId: it.paiId } : {})
} }));

const enviados = $('Preparar Pastas').all();
const respostas = $input.all();
const resultados = enviados.map((it, i) => {
  const chave = it.json.chave;
  const r = (respostas[i] || {}).json || {};
  if (r.error) { return { chave, erro: String((r.error && r.error.message) || r.error).slice(0, 300) }; }
  const status = Number(r.statusCode);
  const corpo = (r.body && typeof r.body === 'object') ? r.body : {};
  if (status >= 200 && status < 300 && corpo.id) { return { chave, id: String(corpo.id) }; }
  const motivo = corpo.message ? String(corpo.message) : JSON.stringify(corpo);
  return { chave, erro: ('HTTP ' + (status || '?') + ' - ' + motivo).slice(0, 400) };
});
return [{ json: { corpo: JSON.stringify({ resultados }) } }];

const ctx = $('Checar Permissao').first().json;
// O projeto e a pasta vem so do servidor/validacao: o workflow do navegador nunca traz projectId nem parentFolderId.
return ctx.itens.map(it => ({ json: {
  chave: it.chave,
  baseUrl: ctx.baseUrl,
  instancia: ctx.instancia,
  corpo: Object.assign({}, it.workflow, { projectId: ctx.projetoId }, it.pastaId ? { parentFolderId: it.pastaId } : {})
} }));

const enviados = $('Preparar Workflows').all();
const respostas = $input.all();
const resultados = enviados.map((it, i) => {
  const chave = it.json.chave;
  const r = (respostas[i] || {}).json || {};
  if (r.error) { return { chave, erro: String((r.error && r.error.message) || r.error).slice(0, 300) }; }
  const status = Number(r.statusCode);
  const corpo = (r.body && typeof r.body === 'object') ? r.body : {};
  if (status >= 200 && status < 300 && corpo.id) { return { chave, id: String(corpo.id) }; }
  const motivo = corpo.message ? String(corpo.message) : JSON.stringify(corpo);
  return { chave, erro: ('HTTP ' + (status || '?') + ' - ' + motivo).slice(0, 400) };
});
const criados = resultados.filter(r => r.id);
const nomes = enviados.filter((it, i) => resultados[i].id).map(it => it.json.corpo.name).join(' | ').slice(0, 1800);
return [{ json: { corpo: JSON.stringify({ resultados }), logQtd: criados.length, logNomes: nomes } }];

const ctx = $('Checar Permissao').first().json;
return ctx.itens.map(it => ({ json: {
  chave: it.chave,
  id: it.id,
  baseUrl: ctx.baseUrl,
  instancia: ctx.instancia,
  corpo: it.workflow
} }));

const enviados = $('Preparar Atualizacoes').all();
const respostas = $input.all();
const resultados = enviados.map((it, i) => {
  const chave = it.json.chave;
  const r = (respostas[i] || {}).json || {};
  if (r.error) { return { chave, erro: String((r.error && r.error.message) || r.error).slice(0, 300) }; }
  const status = Number(r.statusCode);
  const corpo = (r.body && typeof r.body === 'object') ? r.body : {};
  if (status >= 200 && status < 300 && corpo.id) { return { chave, id: String(corpo.id) }; }
  const motivo = corpo.message ? String(corpo.message) : JSON.stringify(corpo);
  return { chave, erro: ('HTTP ' + (status || '?') + ' - ' + motivo).slice(0, 400) };
});
return [{ json: { corpo: JSON.stringify({ resultados }) } }];
